package it.comune.trieste.ouf.ingestion;
import java.time.Duration;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;import org.springframework.stereotype.Service;
@Service @ConditionalOnBean(RuntimePorts.OnboardingReviewPort.class) public class OnboardingReviewDispatcher {private final OnboardingReviewRepository queue;private final RuntimePorts.OnboardingReviewPort onboarding;public OnboardingReviewDispatcher(OnboardingReviewRepository queue,RuntimePorts.OnboardingReviewPort onboarding){this.queue=queue;this.onboarding=onboarding;}public Optional<UUID> dispatchOne(String worker){var claimed=queue.claim(worker,Duration.ofMinutes(2));if(claimed.isEmpty())return Optional.empty();var c=claimed.orElseThrow();try{var receipt=onboarding.request(c.issueId(),c.sourceId(),c.evidenceRef(),c.correlationId(),c.idempotencyKey());if(!receipt.durable()||receipt.reviewRef()==null||receipt.reviewRef().isBlank())throw new IllegalStateException("ING_ONBOARDING_REVIEW_NOT_DURABLE");queue.acknowledge(c,receipt.reviewRef());}catch(RuntimeException e){String code=e.getMessage()!=null&&e.getMessage().matches("ING_[A-Z0-9_]{1,76}")?e.getMessage():"ING_ONBOARDING_REVIEW_FAILED";queue.fail(c,code,false);}return Optional.of(c.requestId());}}
